declare(strict_types=1);require __DIR__.'/../lib/bootstrap.php';require_once CM_LIB.'/view.php';$admin=cm_require_admin();
cm_schema_gate('property_templates', 'settings');$error='';
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){cm_require_csrf();$name=mb_substr(trim((string)($_POST['name']??'')),0,100);$lines=preg_split('/\R/',trim((string)($_POST['fields']??'')));$fields=[];$used=[];foreach($lines as$line){$line=trim($line);if($line==='')continue;[$label,$type]=array_pad(array_map('trim',explode('|',$line,2)),2,'text');$label=mb_substr($label,0,80);$type=strtolower($type);if(!in_array($type,['text','textarea','date','number'],true))$type='text';$key=strtolower(trim((string)preg_replace('/[^a-z0-9]+/i','_',$label),'_'));if($key==='')continue;$base=$key;$n=2;while(isset($used[$key]))$key=$base.'_'.$n++;$used[$key]=true;$fields[]=['key'=>$key,'label'=>$label,'type'=>$type];if(count($fields)>=12)break;}
 if($name==='')$error='Give the template a name.';elseif(!$fields)$error='Add at least one field.';else{try{cm_insert('INSERT INTO property_template(name,fields_json,created_at,updated_at)VALUES(?,?,?,?)',[$name,json_encode($fields,JSON_UNESCAPED_UNICODE),cm_now(),cm_now()]);cm_audit('property_template.created','',null,$name.' created by '.(string)$admin['email']);cm_flash('Property template created. It is now available in Add property and Settings.');cm_redirect('admin/property-templates.php');}catch(Throwable$e){ $dup=str_contains($e->getMessage(),'1062')||stripos($e->getMessage(),'duplicate')!==false; if($dup){$error='That template name is already in use.';}else{error_log('property template create failed: '.$e->getMessage());$error='The template could not be saved and nothing was created. Check Update & backup for a waiting database update; the server error log has the detail.';}}}
}
$templates=[];try{$templates=cm_all('SELECT * FROM property_template ORDER BY name');}catch(Throwable$e){}cm_head('Property templates','',true);cm_render_flashes();cm_admin_nav('settings');cm_admin_subnav('settings','property_templates','Property templates');?>
<p class="sub">Create a reusable property type without changing the database. Keep it simple: one field per line.</p><?php if($error!==''):?><div class="note note-error"><?=e($error)?></div><?php endif;?>
<div class="page-grid"><div><div class="card"><h2>New template</h2><form method="post"><?=cm_csrf_field()?><div class="row"><label class="lbl">Template name</label><input name="name" maxlength="100" required placeholder="Pool service, Vehicle, Rental property"></div><div class="row"><label class="lbl">Fields</label><textarea name="fields" rows="9" required placeholder="Registration number | text&#10;Service date | date&#10;Meter reading | number&#10;Technician notes | textarea"></textarea><div class="hint">One per line: Label | type. Types: text, textarea, date, number. Up to 12 fields.</div></div><button class="btn" type="submit">Create template</button></form></div></div><aside class="side-rail"><div class="card"><h2>What stays shared</h2><p class="small">Every custom type also gets name, service address, suburb, access notes, property notes, client, jobs and history.</p><p class="small">Custom fields remain admin-only and never appear through shared URLs.</p></div></aside></div>
<div class="card mt-16"><div class="card-head"><h2>Templates</h2><span class="spacer"></span><span class="muted small"><?=count($templates)?></span></div><?php if(!$templates):?><div class="empty-state"><h3>No custom templates</h3><p>Web, <?=cm_home()?'':'Piano, '?>Salon and General remain available.</p></div><?php endif;?><?php foreach($templates as$t):$fs=json_decode((string)$t['fields_json'],true)?:[];?><div class="list-row"><div><b><?=e((string)$t['name'])?></b><div class="muted small"><?=e(implode(' · ',array_column($fs,'label')))?></div></div><span class="pill pill-approved"><?=count($fs)?> fields</span></div><?php endforeach;?></div><?php cm_foot();?>

